    private void more(){heading("Un peu plus loin.","Vos outils et vos futures connexions, au même endroit.");action("Mes raccourcis",()->{section="shortcuts";render();});action("Envies du soir",()->{section="recommendations";render();});action("Ma bibliothèque · Jellyfin",()->{section="library";render();});action("Mon PC · Moonlight & Parsec",()->{section="pc";render();});action("Ma maison · Home Assistant",()->{section="home";render();});action("Caméra",()->{section="camera";render();});action("Boutons de ma télécommande",()->startActivity(new Intent(this,RemoteBridgeActivity.class)));}
    private void history(){
        heading("Votre fil de lectures.","Les lectures datées, classées du plus récent au plus ancien. Les suggestions sont exclues.");
        LinearLayout filters=new LinearLayout(this);String[][] choices={{"all","Tous les services"},{"com.crunchyroll.crunchyroid","Crunchyroll"},{"com.netflix.ninja","Netflix"},{"com.amazon.amazonvideo.livingroom","Prime Video"},{"ar.tvplayer.tv","TiviMate"}};
        for(String[] choice:choices){Button b=button(choice[1],()->{historyService=choice[0];render();});b.setTextSize(10);b.setCompoundDrawables(null,null,null,null);b.setMinHeight(dp(34));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(36));p.rightMargin=dp(8);filters.addView(b,p);MarOSUI.navState(b,historyService.equals(choice[0]));}HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);hs.addView(filters);content.addView(hs,new LinearLayout.LayoutParams(-1,dp(44)));
        action(historyUnfinished?"Afficher aussi les lectures terminées":"Afficher seulement les lectures en cours",()->{historyUnfinished=!historyUnfinished;render();});
        ContentBridge bridge=new ContentBridge(this);List<ContentBridge.Item> items=bridge.load(historyService,historyUnfinished);
        if(items.isEmpty())note("Aucune lecture récente datée partagée ici. Ouvrez votre service pour retrouver sa propre rubrique de reprise.");
        LinearLayout line=null;for(int at=0;at<items.size();at++){ContentBridge.Item item=items.get(at);if(at%3==0){line=new LinearLayout(this);line.setClipChildren(false);line.setPadding(dp(3),dp(7),dp(3),dp(12));content.addView(line,new LinearLayout.LayoutParams(-1,-2));}ResumeCardView card=new ResumeCardView(this,item,()->{if(!bridge.open(item))toast("Ouvrez ce contenu depuis son application.");},null);card.setTag("history:"+RecentPolicy.seriesKey(item));card.setOnLongClickListener(v->{MarOSUI.choose(this,item.title,"Votre historique reste sous votre contrôle.",new String[]{"Masquer cette série dans MarOS"},n->{bridge.hide(item);render();});return true;});LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,dp(166),1);cp.rightMargin=dp(at%3==2?0:10);line.addView(card,cp);}
        if(line!=null&&items.size()%3!=0)for(int i=items.size()%3;i<3;i++)line.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));
        note("Netflix, Prime Video ou TiviMate peuvent ne pas partager leur historique complet. MarOS mémorise les nouvelles lectures lorsqu’un titre est réellement transmis par leur lecteur. Une simple ouverture d’application n’est jamais présentée comme une vidéo regardée.");
        action("Rétablir les séries masquées",()->{bridge.resetHidden();render();});
        action("Effacer l’historique observé par MarOS…",()->new AlertDialog.Builder(this).setTitle("Effacer l’historique local ?").setMessage("Les historiques de vos services restent conservés.").setPositiveButton("Effacer",(d,w)->{PlaybackHistory.clear(this);render();}).setNegativeButton("Annuler",null).show());
    }
    private String labelFor(String pkg){try{return getPackageManager().getApplicationLabel(getPackageManager().getApplicationInfo(pkg,0)).toString();}catch(Exception e){return pkg;}}
    private void weather(){heading("Votre météo", "La ville que vous choisissez · aucune localisation automatique.");note(data.weatherSummary());note(data.weatherDetails());action("Choisir ou changer de ville",this::weatherLocation);if(!prefs.getString("weather_city", "").isEmpty())action("Actualiser les prévisions",()->job("Météo",()->{data.refreshWeather(true);return data.weatherDetails();},this::render));action("Effacer ma localisation",()->{prefs.prefs().edit().remove("weather_city").remove("weather_summary").remove("weather_details").remove("weather_error").remove("weather_updated").remove("weather_last_attempt").remove("weather_latitude").remove("weather_longitude").remove("weather_location_name").remove("weather_location_city").remove("weather_resolved_query").apply();prefs.changed();render();});note("Open-Meteo et GeoNames reçoivent votre recherche de ville et ses coordonnées pour les prévisions. Actualisation espacée de 30 minutes ; cache local hors connexion.");}
    private void weatherLocation(){LinearLayout form=new LinearLayout(this);form.setOrientation(android.widget.LinearLayout.VERTICAL);form.setPadding(dp(24),0,dp(24),0);EditText city=field(form,"Ville ou code postal",prefs.getString("weather_city", ""),InputType.TYPE_CLASS_TEXT);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Choisir ma ville").setView(form).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{String query=city.getText().toString().trim();if(query.length()<2||query.length()>100){city.setError("Indiquez une ville ou un code postal de 2 à 100 caractères.");return;}prefs.prefs().edit().putString("weather_city",query).putBoolean("show_weather",true).remove("weather_summary").remove("weather_details").remove("weather_error").remove("weather_last_attempt").apply();prefs.changed();dialog.dismiss();job("Météo",()->{data.refreshWeather(true);return data.weatherDetails();},this::render);}));dialog.show();}
    private List<ResolveInfo> apps(){List<ResolveInfo> all=AppCatalog.query(this);Collections.sort(all,(a,b)->a.loadLabel(getPackageManager()).toString().compareToIgnoreCase(b.loadLabel(getPackageManager()).toString()));ArrayList<ResolveInfo> result=new ArrayList<>();HashSet<String> seen=new HashSet<>();for(ResolveInfo r:all)if(seen.add(r.activityInfo.packageName)&&!r.activityInfo.packageName.equals(getPackageName()))result.add(r);return result;}
    private void search(){heading("Qu’est-ce qui te ferait plaisir ?","Une recherche dirigée vers tes applications, sans catalogue publicitaire.");String query=getIntent().getStringExtra("query");if(query==null)query=prefs.getString("phone_pending_search","");getIntent().removeExtra("query");final EditText input=field("Titre, artiste, chaîne…",query);if(!query.isEmpty())prefs.prefs().edit().remove("phone_pending_search").apply();note("Choisis où chercher. Si l’application ne fournit pas de recherche externe, elle s’ouvre avec ton texte copié.");for(ResolveInfo app:apps()){String pkg=app.activityInfo.packageName;if(prefs.category(pkg).equals("outils"))continue;action("Chercher dans "+app.loadLabel(getPackageManager()),()->HubData.search(this,input.getText().toString(),pkg));}action("Chercher sur le Web",()->HubData.open(this,"https://www.google.com/search?q="+android.net.Uri.encode(input.getText().toString()),""));}
    private void shortcuts(){heading("Tes chemins les plus courts","Playlists, sites, caméras ou bibliothèques : garde les liens que tu choisis.");action("＋ Nouveau raccourci",()->shortcutForm(-1,null));JSONArray values=data.shortcuts();for(int i=0;i<values.length();i++){final int index=i;JSONObject item=values.optJSONObject(i);if(item==null)continue;Button b=button(item.optString("label","Raccourci"),()->data.runShortcut(this,item));b.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle(item.optString("label")).setItems(new String[]{"Modifier","Supprimer"},(d,n)->{if(n==0)shortcutForm(index,item);else{JSONArray a=data.shortcuts();a.remove(index);data.saveArray("hub_shortcuts",a);render();}}).show();return true;});content.addView(b);}note("Appui long pour modifier ou supprimer. Les liens disponibles varient selon les applications.");}
    private void shortcutForm(int index,JSONObject existing){LinearLayout form=new LinearLayout(this);form.setOrientation(android.widget.LinearLayout.VERTICAL);form.setPadding(dp(24),0,dp(24),0);EditText label=field(form,"Nom",existing==null?"":existing.optString("label"),1);EditText uri=field(form,"Lien (optionnel)",existing==null?"":existing.optString("uri"),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);EditText pkg=field(form,"Paquet Android (optionnel)",existing==null?"":existing.optString("package"),1);AlertDialog d=new AlertDialog.Builder(this).setTitle("Raccourci personnel").setView(form).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{String name=label.getText().toString().trim(),link=uri.getText().toString().trim(),p=pkg.getText().toString().trim();if(name.isEmpty()||name.length()>100)throw new IllegalArgumentException("Choisis un nom de 1 à 100 caractères.");if(!link.isEmpty()&&!HubData.safeUri(link))throw new IllegalArgumentException("Lien http, https, rtsp ou spotify attendu.");if(!p.isEmpty()&&!LauncherPrefs.validPackage(p))throw new IllegalArgumentException("Nom de paquet invalide.");if(link.isEmpty()&&p.isEmpty())throw new IllegalArgumentException("Ajoute un lien ou une application.");JSONArray a=data.shortcuts();if(index<0&&a.length()>=50)throw new IllegalArgumentException("50 raccourcis maximum.");JSONObject item=new JSONObject().put("label",name).put("uri",link).put("package",p);if(index<0)a.put(item);else a.put(index,item);data.saveArray("hub_shortcuts",a);d.dismiss();render();}catch(Exception e){toast(e.getMessage());}}));d.show();}
    private void agenda(){if(RoomData.guest(this)){heading("Agenda","Masqué en mode invités.");return;}heading("Un œil sur ta journée","Agenda local à cette TV · aucun compte requis.");action("＋ Ajouter un rendez-vous",()->eventForm(-1,null));note(data.nextEventSummary().isEmpty()?"Aucun rendez-vous à venir":data.nextEventSummary());JSONArray a=data.events();ArrayList<JSONObject> list=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null)list.add(o);}Collections.sort(list,(x,y)->Long.compare(x.optLong("time"),y.optLong("time")));for(JSONObject o:list){String title=o.optString("title")+"  ·  "+new SimpleDateFormat("EEE d MMM yyyy · HH:mm",Locale.FRENCH).format(new Date(o.optLong("time")));action(title,()->{int index=-1;JSONArray saved=data.events();for(int i=0;i<saved.length();i++)if(saved.optJSONObject(i)!=null&&saved.optJSONObject(i).optString("id").equals(o.optString("id")))index=i;final int chosen=index;new AlertDialog.Builder(this).setTitle(o.optString("title")).setItems(new String[]{"Modifier","Supprimer"},(d,n)->{if(n==0)eventForm(chosen,o);else{JSONArray events=data.events();events.remove(chosen);data.saveArray("agenda_events",events);render();}}).show();});}note("Les rendez-vous s’affichent sur l’accueil. Cet agenda local n’envoie pas de notifications et ne synchronise aucun calendrier externe.");}
    private void eventForm(int index,JSONObject old){Date when=new Date(old==null?System.currentTimeMillis():old.optLong("time"));LinearLayout form=new LinearLayout(this);form.setOrientation(android.widget.LinearLayout.VERTICAL);form.setPadding(dp(24),0,dp(24),0);EditText title=field(form,"Rendez-vous",old==null?"":old.optString("title"),1),date=field(form,"Date AAAA-MM-JJ",new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(when),1),time=field(form,"Heure HH:mm",new SimpleDateFormat("HH:mm",Locale.ROOT).format(when),1);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Rendez-vous").setView(form).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{String value=title.getText().toString().trim();if(value.isEmpty()||value.length()>120)throw new Exception("Choisis un titre de 1 à 120 caractères.");SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.ROOT);f.setLenient(false);String raw=date.getText().toString().trim()+" "+time.getText().toString().trim();Date parsed=f.parse(raw);if(parsed==null||!f.format(parsed).equals(raw))throw new Exception("Date ou heure invalide.");JSONArray a=data.events();if(index<0&&a.length()>=100)throw new Exception("100 rendez-vous maximum.");JSONObject item=new JSONObject().put("id",old==null?UUID.randomUUID().toString():old.optString("id")).put("title",value).put("time",parsed.getTime());if(index<0)a.put(item);else a.put(index,item);data.saveArray("agenda_events",a);dialog.dismiss();render();}catch(Exception e){toast(e.getMessage()==null?"Date ou heure invalide.":e.getMessage());}}));dialog.show();}
    private void timer(){heading("Un moment pour toi","Un rappel sonore et une notification, même après avoir quitté l’accueil.");timerText=text(timerSummary(this),26,MarOSUI.accent(this));content.addView(timerText);for(int minutes:new int[]{5,15,30,60,90})action(minutes+" minutes",()->setTimer(minutes));EditText custom=field(content,"Durée personnalisée en minutes","",InputType.TYPE_CLASS_NUMBER);action("Démarrer cette durée",()->{try{int minutes=Integer.parseInt(custom.getText().toString().trim());if(minutes<1||minutes>1440)throw new Exception();setTimer(minutes);}catch(Exception e){toast("Choisis une durée entre 1 et 1440 minutes.");}});action("Annuler le minuteur",()->{AlarmManager alarm=(AlarmManager)getSystemService(ALARM_SERVICE);if(alarm!=null)alarm.cancel(timerIntent(this));prefs.prefs().edit().remove("timer_deadline").putLong("timer_last_ack",prefs.prefs().getLong("timer_last_fired",0)).apply();NotificationManager notifications=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(notifications!=null)notifications.cancel(204);prefs.changed();render();});note("Le minuteur ne coupe ni la box ni la télévision. Il est annulé si la box redémarre.");}
    private void setTimer(int minutes){
        try{scheduleTimer(this,minutes);render();toast("Rappel dans "+minutes+" minutes.");}
        catch(RuntimeException e){toast(e.getMessage());}
    }
    public static void scheduleTimer(Context context,int minutes){
        if(minutes<1||minutes>1440)throw new IllegalArgumentException("Choisissez entre 1 et 1440 minutes.");
        AlarmManager manager=(AlarmManager)context.getSystemService(ALARM_SERVICE);
        if(manager==null)throw new IllegalStateException("Service de minuteur indisponible.");
        if(android.os.Build.VERSION.SDK_INT>=31&&!manager.canScheduleExactAlarms())throw new IllegalStateException("Autorisez les alarmes et rappels dans les réglages Android.");
        long deadline=System.currentTimeMillis()+minutes*60000L;
        PendingIntent show=PendingIntent.getActivity(context,203,new Intent(context,HubActivity.class).putExtra("section","timer"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
        manager.setAlarmClock(new AlarmManager.AlarmClockInfo(deadline,show),timerIntent(context));
        LauncherPrefs prefs=new LauncherPrefs(context);
        prefs.prefs().edit().putLong("timer_deadline",deadline).putLong("timer_last_ack",prefs.prefs().getLong("timer_last_fired",0)).putInt("timer_boot_count",android.provider.Settings.Global.getInt(context.getContentResolver(),"boot_count",-1)).apply();prefs.changed();
    }
    public static void cancelTimer(Context context){
        AlarmManager manager=(AlarmManager)context.getSystemService(ALARM_SERVICE);if(manager!=null)manager.cancel(timerIntent(context));
        LauncherPrefs prefs=new LauncherPrefs(context);prefs.prefs().edit().remove("timer_deadline").putLong("timer_last_ack",prefs.prefs().getLong("timer_last_fired",0)).apply();prefs.changed();
    }
    private static PendingIntent timerIntent(Context context){return PendingIntent.getBroadcast(context,204,new Intent(context,TimerReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    public static String timerSummary(Context context){LauncherPrefs state=new LauncherPrefs(context);long deadline=state.prefs().getLong("timer_deadline",0);if(deadline==0)return state.prefs().getLong("timer_last_fired",0)>state.prefs().getLong("timer_last_ack",0)?"Minuteur terminé":"Aucun minuteur en cours";int boot=android.provider.Settings.Global.getInt(context.getContentResolver(),"boot_count",-1);if(state.getInt("timer_boot_count",boot)!=boot){state.prefs().edit().remove("timer_deadline").apply();return "Minuteur annulé au redémarrage";}long seconds=Math.max(0,(deadline-System.currentTimeMillis()+999)/1000);return seconds==0?"Minuteur terminé":String.format(Locale.FRANCE,"%02d:%02d:%02d restantes",seconds/3600,(seconds%3600)/60,seconds%60);}
    public static final class TimerReceiver extends BroadcastReceiver{
        @Override public void onReceive(Context context,Intent intent){
            LauncherPrefs prefs=new LauncherPrefs(context);long now=System.currentTimeMillis(),deadline=prefs.prefs().getLong("timer_deadline",0);
            if(deadline==0||now+1000<deadline)return;
            // Retain completion even on vendors that suppress TV notification banners.
            prefs.prefs().edit().remove("timer_deadline").putLong("timer_last_fired",now).apply();prefs.changed();
            context.sendBroadcast(new Intent(RoomData.ACTION_CONTROL).setPackage(context.getPackageName()).putExtra("command","timer_fired"));
            try{
                NotificationManager nm=(NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE);
                if(nm!=null){
                    NotificationChannel channel=new NotificationChannel("tvhome_timer","Minuteur MarOS",NotificationManager.IMPORTANCE_HIGH);channel.setDescription("Rappels des minuteurs choisis sur la TV");nm.createNotificationChannel(channel);
                    PendingIntent open=PendingIntent.getActivity(context,203,new Intent(context,HubActivity.class).putExtra("section","timer"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
                    Notification notification=new Notification.Builder(context,"tvhome_timer").setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("Ton minuteur est terminé").setContentText("Prends un moment pour toi.").setCategory(Notification.CATEGORY_ALARM).setContentIntent(open).setAutoCancel(true).setTimeoutAfter(300000).build();nm.notify(204,notification);
                }
            }catch(RuntimeException ignored){/* Persistent completion still reaches the launcher. */}
            android.media.ToneGenerator allocated=null;
            try{
                allocated=new android.media.ToneGenerator(android.media.AudioManager.STREAM_NOTIFICATION,65);final android.media.ToneGenerator tone=allocated;
                if(tone.startTone(android.media.ToneGenerator.TONE_PROP_BEEP2,700))new Handler(Looper.getMainLooper()).postDelayed(()->{try{tone.release();}catch(RuntimeException ignored){}},850);
                else tone.release();
            }catch(RuntimeException ignored){if(allocated!=null)try{allocated.release();}catch(RuntimeException alsoIgnored){} }
        }
    }
    private void phone(){
        heading("Du téléphone au grand écran.","Photos, clavier et favoris. Aucun compte, aucune application à installer.");CompanionServer server=CompanionServer.get(this);
        if(!CompanionService.active()&&!phoneClosed&&!startingPhone){startingPhone=true;CompanionService.begin(this);handler.postDelayed(()->{startingPhone=false;if(!isFinishing()&&"phone".equals(section)){if(!CompanionService.active())phoneClosed=true;render();}},350);note("Préparation de votre connexion…");return;}
        if(server.isRunning()&&CompanionService.active()){
            LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);QrView qr=new QrView(this,server.getUrl()+"/#"+server.getPairingCode());row.addView(qr,new LinearLayout.LayoutParams(dp(172),dp(172)));LinearLayout steps=new LinearLayout(this);steps.setOrientation(android.widget.LinearLayout.VERTICAL);steps.setPadding(dp(26),0,0,0);row.addView(steps,new LinearLayout.LayoutParams(0,-2,1));
            steps.addView(text("1. Même Wi-Fi que la TV",16,MarOSUI.TEXT));steps.addView(text("2. Scannez ce QR code",20,MarOSUI.TEXT));steps.addView(text("L’appareil photo du téléphone ouvre la bonne adresse et vous connecte automatiquement.",12,MarOSUI.MUTED));content.addView(row,new LinearLayout.LayoutParams(-1,dp(190)));
            note("Ou saisissez exactement cette adresse dans le navigateur :");content.addView(text(server.getUrl(),22,MarOSUI.accent(this)));content.addView(text("Code  "+server.getPairingCode()+"   ·   session "+CompanionService.remainingMinutes()+" min",17,MarOSUI.TEXT));
            note("Vous pouvez ouvrir Netflix ou changer d’écran : la connexion reste active. Elle se ferme automatiquement après une heure.");action("Fermer la connexion",()->{phoneClosed=true;CompanionService.end(this);handler.postDelayed(this::render,250);});
            action("La page ne s’ouvre pas ?",()->resultDialog("Vérifier le Wi-Fi","Ouvrez l’adresse en http://, sans https.\n\nLe téléphone et la box doivent être sur le même réseau : évitez le Wi-Fi invité et désactivez temporairement le VPN du téléphone.\n\nSi le délai expire encore, vérifiez l’option Isolation des appareils / AP isolation de votre routeur. Certains réseaux bloquent les échanges entre deux appareils Wi-Fi."));
        }else{note(server.getLastError().isEmpty()?"La connexion est fermée.":server.getLastError());action("Connecter mon téléphone",()->{phoneClosed=false;render();});}
    }
    private void library(){if(RoomData.guest(this)){heading("Vidéothèque","Masquée en mode invités.");return;}heading("Ta vidéothèque, à ton rythme","Pour les films et séries personnels d’un futur serveur Jellyfin.");note(data.statusSummary());if(prefs.getString("jellyfin_url","").isEmpty())note("Tu n’as pas de serveur : rien à installer pour utiliser le launcher. Le connecteur est prêt pour plus tard.");action("Configurer / tester Jellyfin",this::libraryForm);if(!prefs.getString("jellyfin_url","").isEmpty()){action("Actualiser : reprendre et ajouts récents",()->job("Bibliothèque",data::refreshLibrary,this::render));action("Ouvrir ma bibliothèque",()->HubData.open(this,prefs.getString("jellyfin_url","")+"/web/",""));for(HubData.Item item:data.libraryItems())action(item.title+"  ·  "+item.subtitle,()->HubData.open(this,item.uri,item.pkg));}note("La reprise provient de Jellyfin. Les applications de streaming fermées ne donnent pas toutes accès à leur progression.");}
    private void libraryForm(){LinearLayout form=new LinearLayout(this);form.setOrientation(android.widget.LinearLayout.VERTICAL);form.setPadding(dp(24),0,dp(24),0);EditText url=field(form,"Adresse du serveur",""+prefs.getString("jellyfin_url","http://"),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI),user=field(form,"Identifiant utilisateur Jellyfin (facultatif)",prefs.getString("jellyfin_user",""),1),token=field(form,"Jeton d’accès (vide = conserver)","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Connexion Jellyfin").setView(form).setNegativeButton("Annuler",null).setNeutralButton("Déconnecter",(d,w)->{prefs.prefs().edit().remove("jellyfin_url").remove("jellyfin_user").remove("library_items").remove("library_updated").remove("library_status").apply();try{secrets.put("jellyfin_token","");}catch(Exception ignored){}render();}).setPositiveButton("Enregistrer et tester",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{String base=HubData.normalizeServer(url.getText().toString()),userValue=user.getText().toString().trim();if(!userValue.isEmpty()&&!userValue.matches("[A-Fa-f0-9-]{32,36}"))throw new Exception("Identifiant utilisateur Jellyfin invalide.");if(!token.getText().toString().isEmpty())secrets.put("jellyfin_token",token.getText().toString());if(secrets.get("jellyfin_token").isEmpty())throw new Exception("Un jeton d’accès est nécessaire.");prefs.prefs().edit().putString("jellyfin_url",base).putString("jellyfin_user",userValue).remove("library_updated").apply();dialog.dismiss();job("Connexion Jellyfin",data::refreshLibrary,this::render);}catch(Exception e){toast(e.getMessage());}}));dialog.show();}
    private void pc(){heading("Du grand écran au grand jeu","Moonlight, Parsec et un PC prêt à se réveiller.");note("Pas encore de PC à réveiller ? Tes applications de jeux restent utilisables directement. Tu pourras renseigner le PC ici plus tard.");action("Ouvrir Moonlight",()->HubData.open(this,"","com.limelight"));action("Ouvrir Parsec",()->HubData.open(this,"","tv.parsec.client"));EditText mac=field("Adresse MAC Ethernet du PC",prefs.getString("pc_mac","")),broadcast=field("Adresse de diffusion du réseau",prefs.getString("pc_broadcast",""));action("Enregistrer le PC",()->{String m=mac.getText().toString().trim();if(!m.replace(":","").replace("-","").matches("[A-Fa-f0-9]{12}")){toast("Adresse MAC invalide.");return;}prefs.prefs().edit().putString("pc_mac",m).putString("pc_broadcast",broadcast.getText().toString().trim()).apply();toast("PC enregistré.");});action("Réveiller mon PC",()->job("Wake-on-LAN",data::wakePc,null));action("Réveiller, puis ouvrir Moonlight",()->{toast("Envoi du réveil…");HubData.work(data::wakePc,(value,success)->{toast(value);if(success)HubData.open(this,"","com.limelight");});});note("Wake-on-LAN doit être activé dans le BIOS et le système du PC. Le paquet magique est envoyé sur ton réseau ; l’application ne peut pas confirmer à elle seule que le PC a démarré.");}
    private void home(){heading("La maison à portée de télécommande","Un connecteur Home Assistant prêt pour ton installation future.");note("Home Assistant est un système pour piloter lumières, volets et autres appareils compatibles. Sans installation chez toi, aucune commande n’est active.");action("Configurer / tester Home Assistant",this::homeForm);if(!prefs.getString("ha_url","").isEmpty()){action("Voir les entités et leurs états",()->job("États de la maison",data::homeStates,null));EditText domain=field("Domaine",prefs.getString("ha_domain","light")),service=field("Action",prefs.getString("ha_service","turn_off")),entity=field("Entité",prefs.getString("ha_entity",""));action("Envoyer cette commande…",()->new AlertDialog.Builder(this).setTitle("Commander la maison").setMessage(domain.getText()+" / "+service.getText()+"\n"+entity.getText()).setNegativeButton("Annuler",null).setPositiveButton("Envoyer",(d,w)->{String a=domain.getText().toString().trim(),b=service.getText().toString().trim(),c=entity.getText().toString().trim();prefs.prefs().edit().putString("ha_domain",a).putString("ha_service",b).putString("ha_entity",c).apply();job("Maison",()->data.homeAction(a,b,c),null);}).show());action("Ajouter un scénario à cet accueil",()->sceneForm(-1,null));JSONArray scenes=data.array("home_scenes");for(int i=0;i<scenes.length();i++){JSONObject scene=scenes.optJSONObject(i);if(scene==null)continue;final int at=i;Button b=button(scene.optString("label","Scénario"),()->new AlertDialog.Builder(this).setTitle(scene.optString("label")).setMessage("Envoyer "+scene.optString("domain")+"."+scene.optString("service")+" à "+scene.optString("entity")+" ?").setNegativeButton("Annuler",null).setPositiveButton("Lancer",(d,w)->job("Scénario",()->data.homeAction(scene.optString("domain"),scene.optString("service"),scene.optString("entity")),null)).show());b.setOnLongClickListener(v->{new AlertDialog.Builder(this).setItems(new String[]{"Modifier","Supprimer"},(d,n)->{if(n==0)sceneForm(at,scene);else{JSONArray list=data.array("home_scenes");list.remove(at);data.saveArray("home_scenes",list);render();}}).show();return true;});content.addView(b);}}note("Exemples à configurer dans Home Assistant : Soirée cinéma, Ambiance, Lumières. Aucune action sur tes appareils n’est exécutée automatiquement.");}
    private void homeForm(){LinearLayout form=new LinearLayout(this);form.setOrientation(android.widget.LinearLayout.VERTICAL);form.setPadding(dp(24),0,dp(24),0);EditText url=field(form,"Adresse Home Assistant",prefs.getString("ha_url","http://"),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI),token=field(form,"Jeton longue durée (vide = conserver)","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Connexion à la maison").setView(form).setNegativeButton("Annuler",null).setNeutralButton("Déconnecter",(d,w)->{prefs.prefs().edit().remove("ha_url").apply();try{secrets.put("ha_token","");}catch(Exception ignored){}render();}).setPositiveButton("Enregistrer et tester",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{String base=HubData.normalizeServer(url.getText().toString());if(!token.getText().toString().isEmpty())secrets.put("ha_token",token.getText().toString());if(secrets.get("ha_token").isEmpty())throw new Exception("Ajoute le jeton longue durée de ton profil Home Assistant.");prefs.putString("ha_url",base);dialog.dismiss();job("Home Assistant",data::testHomeAssistant,this::render);}catch(Exception e){toast(e.getMessage());}}));dialog.show();}
    private void preferenceChoice(String key,String label,String fallback,String[] choices){action(label+" : "+prefs.getString(key,fallback),()->new AlertDialog.Builder(this).setTitle(label).setItems(choices,(d,n)->{prefs.putString(key,choices[n]);render();}).show());}
    private String viewingCriteria(String more){return "Je cherche un film ou une série. Humeur : "+prefs.getString("recommendation_mood","Me détendre")+". Genre : "+prefs.getString("recommendation_genre","Tous les genres")+". Temps disponible : "+prefs.getString("recommendation_duration","Environ 90 minutes")+". Je consulte notamment Netflix, Prime Video, Crunchyroll et YouTube. "+more;}
    private void recommendations(){
        heading("Qu’est-ce qu’on regarde ce soir ?","Une envie, un peu de temps, quelques pistes à explorer.");
        preferenceChoice("recommendation_mood","Mon humeur","Me détendre",new String[]{"Me détendre","Rire","M’évader","Frissonner","Découvrir","Passer un moment en famille"});
        preferenceChoice("recommendation_genre","Le genre","Tous les genres",new String[]{"Tous les genres","Animation / Anime","Comédie","Science-fiction","Aventure","Thriller","Documentaire","Drame","Fantastique"});
        preferenceChoice("recommendation_duration","Mon temps disponible","Environ 90 minutes",new String[]{"Un épisode de moins de 30 minutes","Un épisode de moins d’une heure","Environ 90 minutes","Moins de deux heures","J’ai toute la soirée"});
        EditText extra=field("Une envie particulière (facultatif)",prefs.getString("recommendation_extra",""));
        action("Explorer des idées sur le Web",()->{String more=extra.getText().toString().trim();prefs.putString("recommendation_extra",more);HubData.open(this,"https://www.google.com/search?q="+android.net.Uri.encode("recommandation "+viewingCriteria(more)),"");});
        action("Rechercher un titre dans mes applications",()->{String more=extra.getText().toString().trim();if(!more.isEmpty())prefs.putString("phone_pending_search",more);section="search";render();});
        if(!prefs.getString("assistant_url","").isEmpty())action("Demander trois idées à mon assistant",()->{String more=extra.getText().toString().trim();prefs.putString("recommendation_extra",more);job("Les idées de ton assistant",()->data.recommend(viewingCriteria(more)),this::render);});
        action("Configurer mon assistant facultatif",this::assistantForm);
        String result=prefs.getString("recommendation_result","");if(!result.isEmpty()){note("Dernières idées de ton assistant");note(result);}
        note("Le Web s’ouvre uniquement sur demande. Le connecteur IA demande un serveur compatible Ollama avec un modèle disponible ; aucune IA n’est installée sur la box. Les titres suggérés et leur disponibilité restent à vérifier dans tes applications.");
    }
    private void assistantForm(){
        LinearLayout form=new LinearLayout(this);form.setOrientation(android.widget.LinearLayout.VERTICAL);form.setPadding(dp(24),0,dp(24),0);
        EditText url=field(form,"Adresse du serveur Ollama",prefs.getString("assistant_url","http://"),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI),model=field(form,"Nom exact du modèle installé",prefs.getString("assistant_model",""),1),token=field(form,"Jeton facultatif (vide = conserver)","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Assistant facultatif").setView(form).setNegativeButton("Annuler",null).setNeutralButton("Déconnecter",(d,w)->{prefs.prefs().edit().remove("assistant_url").remove("assistant_model").remove("recommendation_result").apply();try{secrets.put("assistant_token","");}catch(Exception ignored){}render();}).setPositiveButton("Enregistrer",null).create();
        dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{String base=HubData.normalizeServer(url.getText().toString()),name=model.getText().toString().trim();if(name.isEmpty()||name.length()>120||!name.matches("[A-Za-z0-9._:/-]+"))throw new Exception("Indique le nom exact du modèle sur ton serveur.");String key=token.getText().toString();if(!key.isEmpty())secrets.put("assistant_token",key);prefs.prefs().edit().putString("assistant_url",base).putString("assistant_model",name).apply();dialog.dismiss();render();toast("Connecteur enregistré. Lance une demande pour tester le modèle.");}catch(Exception e){toast(e.getMessage());}}));dialog.show();
    }
    private void sceneForm(int index,JSONObject old){LinearLayout form=new LinearLayout(this);form.setOrientation(android.widget.LinearLayout.VERTICAL);form.setPadding(dp(24),0,dp(24),0);EditText label=field(form,"Nom du scénario",old==null?"Soirée cinéma":old.optString("label"),1),domain=field(form,"Domaine",old==null?"scene":old.optString("domain"),1),service=field(form,"Action",old==null?"turn_on":old.optString("service"),1),entity=field(form,"Entité",old==null?"scene.":old.optString("entity"),1);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Raccourci maison").setView(form).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{String a=label.getText().toString().trim(),b=domain.getText().toString().trim(),c=service.getText().toString().trim(),e=entity.getText().toString().trim();if(a.isEmpty()||a.length()>100||!b.matches("[a-z_]{2,40}")||!c.matches("[a-z_]{2,60}")||!e.matches("[a-z_]+\\.[a-z0-9_]+"))throw new Exception("Vérifie les quatre champs.");JSONArray list=data.array("home_scenes");if(index<0&&list.length()>=20)throw new Exception("20 scénarios maximum.");JSONObject value=new JSONObject().put("label",a).put("domain",b).put("service",c).put("entity",e);if(index<0)list.put(value);else list.put(index,value);data.saveArray("home_scenes",list);dialog.dismiss();render();}catch(Exception ex){toast(ex.getMessage());}}));dialog.show();}
    private void camera(){heading("Un regard sur la maison","Ouvre une caméra ou une sonnette qui fournit une adresse compatible.");note("La vue s’ouvre dans le navigateur ou le lecteur installé sur la box. Une incrustation au-dessus de toutes les applications demande des fonctions supplémentaires du système.");EditText url=field("Adresse du flux ou de la page caméra",prefs.getString("camera_url",""));action("Enregistrer et ouvrir",()->{String value=url.getText().toString().trim();if(!HubData.safeUri(value)){toast("Lien http, https ou rtsp attendu, sans mot de passe dans l’adresse.");return;}prefs.putString("camera_url",value);HubData.open(this,value,"");});}
